globalThis.STORY_ZW_PAL_FR=Object.assign(globalThis.STORY_ZW_PAL_FR||{},{
'兄弟':{
'紫微':{title:"Un petit roi à la maison",story:"Zi Wei dans le palais de la Fratrie : vos frères et sœurs ou vos proches du même âge ont souvent des idées arrêtées, des capacités, et une certaine autorité naturelle. Votre relation ressemble plutôt à un respect mutuel, sans grandes effusions. Ils interviennent aux moments décisifs, mais ont aussi l’habitude de vous conseiller selon leurs propres critères.",scenes:["Quand vous changez de travail, votre aîné vous demande d’abord le salaire et le titre, puis vous livre une analyse complète de ce que « vous devriez faire ».","En vous répartissant les tâches avec un associé, vous constatez qu’il veut toujours trancher, jusqu’à caler l’heure des réunions sur ses habitudes."],advice:"Remerciez-les sincèrement pour leur aide, mais gardez pour vous le dernier mot."},
'紫微·天府':{title:"Deux grandes demeures côte à côte",story:"Zi Wei et Tian Fu dans le palais de la Fratrie : vos frères et sœurs ou proches du même âge sont généralement posés, avec le sens de l’argent, et vous êtes l’un pour l’autre un appui en cas de besoin. Chacun a ses positions, vous vous respectez et vous mêlez peu des affaires de l’autre. Côté trésorerie, la famille ou les vieux amis sont souvent votre dernier filet de sécurité.",scenes:["Il vous manque soudain une somme pour un apport ; un coup de fil à votre sœur, elle vous demande à quoi elle servira, puis vous la prête.","Vous gérez peut-être avec un frère la maison de vos parents ; vous n’êtes pas toujours d’accord, mais chacun accepte de suivre les règles."],advice:"Prêt d’argent ou partage des tâches, mettez tout par écrit et clairement : c’est ainsi qu’une relation solide dure."},
'紫微·天相':{title:"Un contrat de famille fondé sur la parole donnée",story:"Vos frères et sœurs ou proches du même âge tiennent aux usages et à l’équité ; votre relation paraît digne et ordonnée. Quand la famille traverse quelque chose, on s’accorde selon les règles, et on attend souvent de vous que vous préserviez l’ensemble. L’appui : quelqu’un accepte toujours d’organiser les choses. La friction : on tient tant à la face que les vérités ont du mal à sortir.",scenes:["Pour les cadeaux de fin d’année, qui donne quoi et combien, vous fixez d’abord les proportions dans le groupe familial avant d’agir.","Avec un associé de votre âge, les conditions sont parfaitement négociées, mais personne n’ose dire le premier ce qui le dérange."],advice:"Mettez la face de côté et prévoyez régulièrement des moments pour vous parler franchement : la relation n’en sera que plus solide."},
'紫微·破軍':{title:"Des princes partis chacun avec leur armée",story:"Vos frères et sœurs ou proches du même âge ont une forte personnalité et le goût d’entreprendre ; chacun suit sa route, et la relation connaît de grands hauts et bas, très proche un temps, distante ensuite. S’associer avec eux, c’est souvent un départ enthousiaste et un virage en cours de route. L’argent circule vite dans les deux sens, gardez une marge.",scenes:["Votre frère cadet quitte soudain son emploi pour créer son entreprise et vous propose de le suivre ; vous êtes tenté mais inquiet pour votre épargne.","Vous vous brouillez peut-être avec un proche pour une affaire de famille au point de ne plus vous parler, puis six mois plus tard vous dînez ensemble comme si de rien n’était."],advice:"Avant de collaborer, convenez de la façon de vous retirer, et séparez affection et affaires : personne ne sera trop blessé."},
'紫微·七殺':{title:"Deux généraux à la même longue table",story:"Vos frères et sœurs ou proches du même âge sont affirmés, décidés et très actifs ; entre vous, peu de mollesse, beaucoup de franchise. En cas de désaccord, personne ne cède, mais si quelqu’un d’extérieur s’en prend à vous, ils sont les premiers à vous défendre. Pour s’associer, mieux vaut que chacun gère son domaine plutôt que de tout décider ensemble.",scenes:["En voyage familial, votre frère et vous avez chacun préparé un itinéraire, et sur l’aire d’autoroute vous débattez encore de la prochaine étape.","Quand un ami et collègue commet une erreur, vous la prenez sur vous sans hésiter, puis le sermonnez un peu en privé."],advice:"Clarifiez d’abord qui gère quoi : la force que vous mettez à vous affronter deviendra un soutien mutuel."},
'紫微·貪狼':{title:"Un repas de famille animé et fastueux",story:"Vos frères et sœurs ou proches du même âge sont doués pour beaucoup de choses, savent profiter de la vie et ont un large cercle d’amis ; avec eux, c’est toujours vivant et amusant. Votre lien se nourrit souvent de sorties, de bonnes tables et de passions communes. Les frictions viennent surtout des habitudes de dépense, ou d’une comparaison discrète : qui vit le plus brillamment.",scenes:["Aux repas de famille, c’est toujours votre sœur qui choisit le restaurant, forcément de ceux où l’on fait la queue et où il faut réserver à l’avance.","Vous vous passionnez peut-être pour le camping avec un ami proche ; l’équipement s’accumule, et qui a payé quoi devient de plus en plus flou."],advice:"Sortez ensemble, mais que chacun règle sa part : votre affection ne sera pas plombée par la comparaison."},
'天機':{title:"Une bande de conseillers pleins d’idées",story:"Vos frères et sœurs ou proches du même âge sont intelligents, vifs et pleins d’idées, et vos conversations partent dans tous les sens. Votre relation varie selon les étapes de la vie, parfois très proche, parfois chacun de son côté. {{B:天機:Vos échanges sont vivants, et ils vous aident à trouver des solutions.|Vos idées divergent souvent, et les contacts sont moins réguliers.}}",scenes:["Vous voulez acheter une voiture ; une seule question à votre frère, et il vous envoie cinq comparateurs et trois formules de paiement.","Avec votre associé, chaque réunion fait naître de nouvelles idées, et le plan en est à sa septième version sans avoir commencé."],advice:"Après avoir écouté les suggestions de chacun, fixez une date butoir : une idée ne compte que si elle se concrétise."},
'天機·太陰':{title:"Une fenêtre où l’on échange ses confidences au clair de lune",story:"Vos frères et sœurs ou proches du même âge sont doux, délicats et très sensibles ; vos échanges tournent autour des confidences et de l’entraide, et l’influence des sœurs ou des proches féminines est souvent particulièrement marquée. La relation évolue au gré des déménagements, des études et du travail, et vous vivez peut-être dans des villes différentes. La friction : vous êtes tous sensibles, une phrase peut vous occuper longtemps.",scenes:["Quand vous n’avez pas le moral, votre petite sœur vous envoie un simple « ça va en ce moment ? », et vous avez les larmes aux yeux.","Parce que votre cousine n’a pas répondu à votre message dans le groupe, vous vous demandez toute la journée si vous avez dit quelque chose de travers."],advice:"Si quelque chose vous semble bizarre, demandez directement : c’est bien moins épuisant que de deviner toute la soirée."},
'天機·巨門':{title:"Un club de débat familial qui ne s’arrête jamais",story:"Vos frères et sœurs ou proches du même âge sont intelligents et éloquents ; vous pouvez parler en profondeur, mais aussi vous chamailler facilement. Quand les points de vue divergent, on va jusqu’au bout, et les malentendus viennent surtout de paroles trop rapides. Ils peuvent vous aider à décortiquer un problème, mais leurs critiques ne prennent pas de gants.",scenes:["À un repas de famille, vous débattez des prix de l’immobilier avec votre frère de l’entrée jusqu’au dessert.","Vous débattez longuement d’un détail avec votre associé dans un groupe de discussion, pour découvrir à la fin que vous pensiez à peu près la même chose."],advice:"Avant de débattre, vérifiez que vous parlez bien de la même chose : bien des disputes deviendront inutiles."},
'天機·天梁':{title:"Un aîné mûr qui aime donner des conseils",story:"Vos frères et sœurs ou proches du même âge ont de l’expérience et aiment analyser ; ils jouent souvent le rôle de conseiller et de protecteur. Il y a peut-être un écart d’âge entre vous, ou l’un de vous a mûri particulièrement tôt. L’appui : il y a toujours quelqu’un pour vous conseiller. La friction : un ton moralisateur, on a l’impression de recevoir une leçon.",scenes:["Vous annoncez vouloir démissionner pour voyager, et votre sœur vous envoie d’abord un article sur l’assurance et l’épargne de précaution.","Vous êtes peut-être celui qu’on appelle pour régler les différends, et vous passez souvent vos week-ends au téléphone à écouter les plaintes des autres."],advice:"Avant de conseiller, demandez : « Tu veux que je t’écoute, ou que je te donne mon avis ? »"},
'太陽':{title:"La lampe qui éclaire toute la maison",story:"Vos frères et sœurs ou proches du même âge sont chaleureux, généreux et loyaux, et l’influence des frères ou des proches masculins est particulièrement marquée. Vous avez l’habitude de vous entraider, en donnant plus qu’en comptant. {{B:太陽:Vous vous soutenez beaucoup, et la relation est claire et lumineuse.|Vous donnez peut-être plus sans être remarqué, ou l’un de vos proches a une vie plus difficile.}}",scenes:["Quand votre frère cadet déménage, vous lui prêtez votre voiture sans discuter et portez des meubles jusqu’à minuit.","Vous êtes souvent celui qui règle l’addition lors des sorties ; on vous promet de vous rembourser, et vous répondez toujours « on verra la prochaine fois »."],advice:"Gardez votre générosité, mais avant de vous lancer, vérifiez ce qu’il reste dans votre propre réservoir."},
'太陽·太陰':{title:"Une famille où le Soleil et la Lune se relaient",story:"Vos frères et sœurs ou proches du même âge allient force et douceur : peut-être avez-vous des frères et des sœurs, ou la même personne souffle le chaud et le froid. Votre relation est chaleureuse, mais les variations d’humeur sont nettes. Selon les périodes, ce n’est pas la même personne qui vous aide, et les frictions viennent souvent d’attentes décalées.",scenes:["Quand la famille a un souci, votre frère court les démarches administratives le jour, et votre sœur tient compagnie à votre mère le soir.","Une période, vous appelez votre sœur tous les jours ; une autre, vous restez un mois sans nouvelles."],advice:"N’exigez pas que chacun vous montre son affection de la même façon : chaque lumière compte."},
'太陽·巨門':{title:"Une famille qui parle fort mais au grand cœur",story:"Vos frères et sœurs ou proches du même âge sont chaleureux et n’ont pas peur de parler ; dans les discussions, le ton monte vite. Les accrochages ne manquent pas, mais ils visent les faits plutôt que les personnes. Les malentendus apportés par Ju Men finissent généralement, sous la lumière de Tai Yang, par être mis à plat. Vous êtes faits pour faire ensemble des choses qui demandent communication et expression.",scenes:["Le groupe familial se dispute pour savoir qui accompagne les parents à leurs rendez-vous médicaux, puis finit par établir un planning de roulement.","Vous vous associez peut-être avec un proche dans l’enseignement ou la vente, et votre aplomb à l’oral fait décoller l’affaire."],advice:"Après une dispute, pensez à conclure : un « j’ai été trop brusque tout à l’heure » sauve bien des choses."},
'太陽·天梁':{title:"Des frères et sœurs grandis à l’ombre d’un grand arbre",story:"Vos frères et sœurs ou proches du même âge ont une stature d’aîné, sont chaleureux et attachés aux liens ; l’entraide entre vous est très présente. Vous êtes peut-être celui dont on prend soin, ou celui qui porte tout le monde. L’appui : dans les moments durs, quelqu’un tient toujours bon. La friction : trop de contrôle, on ne peut s’empêcher d’intervenir dans la vie de l’autre.",scenes:["Vous êtes hospitalisé quelques jours, votre frère prend un congé pour vous tenir compagnie, et en profite pour vous dire d’arrêter les grignotages nocturnes.","Vous êtes peut-être celui qui, parmi vos proches, corrige les CV et recommande pour des postes."],advice:"Tout en prenant soin des autres, laissez-leur de l’espace : ce n’est pas grave s’ils trébuchent une fois tout seuls."},
'武曲':{title:"Des frères et sœurs d’acier qui comptent juste",story:"Vos frères et sœurs ou proches du même âge sont droits et pragmatiques, préfèrent les actes aux mots doux ; vos échanges sont mesurés et les limites d’argent sont nettes. Le palais de la Fratrie renseigne aussi sur la trésorerie, et Wu Qu ici vous rappelle que votre argent disponible repose sur votre propre planification. {{B:武曲:Vous pouvez vous soutenir financièrement les uns les autres.|Chacun gère plutôt ses affaires de son côté.}}",scenes:["Vous offrez avec votre sœur un réfrigérateur à vos parents, et elle envoie un tableau qui calcule la part de chacun.","Vous tenez peut-être un petit commerce avec un proche : il travaille dur et concrètement, mais parle peu de ce qu’il ressent."],advice:"Appréciez leur franchise et exprimez aussi vos besoins : une relation robuste peut avoir de la chaleur."},
'武曲·天府':{title:"Un trésor familial gardé",story:"Vos frères et sœurs ou proches du même âge accordent de l’importance à l’argent et à la prudence, et savent épargner et gérer. Leur aide est très concrète : vous recommander pour un poste, avancer de l’argent à court terme. La relation est plutôt rationnelle, l’affection ne s’affiche pas forcément. Côté trésorerie, vous avez généralement un appui, mais on regardera aussi comment vous utilisez la somme.",scenes:["Vous voulez emprunter une somme en urgence ; votre frère accepte vite, mais vous demande au passage votre plan de remboursement.","Vous gérez peut-être l’épargne de vos parents avec votre sœur, toutes deux si prudentes que chaque mouvement est vérifié."],advice:"Pour tout prêt, établissez un calendrier écrit : protéger votre crédit, c’est protéger votre relation."},
'武曲·天相':{title:"Un directeur financier familial fiable",story:"Vos frères et sœurs ou proches du même âge sont sérieux et tiennent parole ; ils aident volontiers, mais avec des principes. Vos échanges sont équitables, on se doit rarement quelque chose. Ce sont eux qui peuvent vous aider avec les papiers et coordonner les petites affaires. La friction : beaucoup de règles, et parfois l’impression d’être encadré.",scenes:["Pour le remboursement de l’assurance de vos parents, c’est votre frère qui a rassemblé tous les justificatifs.","En colocation avec un ami, il calcule le partage de l’eau, de l’électricité et du gaz au centime près."],advice:"Fixez les règles d’avance, et vous serez l’un pour l’autre les partenaires les plus reposants."},
'武曲·七殺':{title:"Deux épées que chacun aiguise de son côté",story:"Vos frères et sœurs ou proches du même âge ont une personnalité ferme, indépendante et décidée. Vous prenez rarement des nouvelles l’un de l’autre, et chacun se bat plutôt de son côté. Associés, vous êtes très efficaces, mais en désaccord vous vous affrontez de front. Pour la trésorerie, il faut surtout compter sur vous-même, et les prêts entre vous créent facilement des frictions.",scenes:["Pour rénover la vieille maison familiale, vous choisissez l’entrepreneur en trois jours, mais avec une grosse dispute au milieu.","Vous créez peut-être une entreprise avec un proche : six premiers mois au pas de charge, puis un blocage sur la répartition des bénéfices."],advice:"Avant de collaborer, mettez les responsabilités noir sur blanc : plus les caractères sont durs, plus ils ont besoin de règles."},
'武曲·破軍':{title:"Une expédition sur un coup de tête",story:"Vos frères et sœurs ou proches du même âge osent foncer, dépenser et changer de voie ; la relation connaît de grands hauts et bas, et vous vivez peut-être un temps dans des endroits différents. Les échanges d’argent sont pleins d’imprévus, gardez une marge de trésorerie. L’avantage : face aux bouleversements, leur énergie peut vous donner l’élan nécessaire.",scenes:["Votre cousin annonce soudain partir en Australie avec un visa vacances-travail, et vous emprunte le prix du billet avant de partir.","Vous ouvrez peut-être une boutique avec un proche, et les travaux coûtent le double du budget prévu."],advice:"Prêtez selon vos moyens : le montant maximal est celui qui, s’il ne revenait pas, ne changerait rien à votre vie."},
'武曲·貪狼':{title:"Des compagnons qui savent gagner et s’amuser",story:"Vos frères et sœurs ou proches du même âge ont le flair pour l’argent et savent aussi profiter de la vie. Vous montez peut-être un petit commerce ensemble, ou partagez une passion. Quand l’ambiance est bonne, on se dit tout ; au moment de partager les gains, on compte facilement. Peu de contacts dans la jeunesse, peut-être, mais avec l’âge vous vous rapprochez.",scenes:["Vous tenez un stand au marché avec votre frère, et quand le week-end a été bon, vous allez manger un barbecue coréen.","Lors d’un achat groupé entre amis, c’est vous qui négociez le prix, collectez l’argent et faites les comptes."],advice:"Partagez le jour même l’argent gagné ensemble : la bonne ambiance durera plus longtemps."},
'天同':{title:"Une famille qui bavarde autour de la fondue",story:"Vos frères et sœurs ou proches du même âge sont doux et faciles à vivre, vous ne comptez pas entre vous ; la relation est détendue, faite de présence plus que d’exigences. L’appui : un soutien émotionnel. La friction : quand il faut agir, chacun attend que l’autre s’en charge. {{B:天同:La famille est harmonieuse et les échanges se font naturellement.|Chacun garde peut-être ses soucis pour lui ; on reste aimable en surface, mais on se parle rarement en profondeur.}}",scenes:["Les réunions de famille n’ont rien de spécial : on mange devant une émission de variétés et on éclate de rire.","Vous avez promis avec vos frères et sœurs de ranger la maison familiale, et trois mois plus tard rien n’a bougé."],advice:"La légèreté est une chance ; pour les choses importantes, désignez un responsable et une date."},
'天同·太陰':{title:"Une théière de thé tiède infusée lentement",story:"Vos frères et sœurs ou proches du même âge sont délicats et tendres, avec beaucoup d’échanges affectifs ; les sœurs ou les proches féminines sont particulièrement attentionnées. Vous vous affrontez rarement, mais vos émotions se communiquent facilement. L’appui : quelqu’un comprend ce que vous ressentez. La friction : vous vous ménagez tant que beaucoup de choses restent non dites.",scenes:["Le soir de votre rupture, votre petite sœur arrive avec du poulet frit et regarde une série avec vous toute la nuit.","Parce que vous n’osez pas refuser une demande de votre cousin, votre week-end est encore pris en entier."],advice:"Au-delà de la douceur, entraînez-vous à dire « non » : la relation ne refroidira pas pour autant."},
'天同·巨門':{title:"Un repas où les confidences n’en finissent pas",story:"Vos frères et sœurs ou proches du même âge sont riches en émotions, mais la communication bute souvent sur des malentendus. Aimables en surface, ils gardent parfois de petites rancœurs qui, avec le temps, tournent au silence boudeur. L’appui : on peut se plaindre ensemble et décompresser. La friction : on ne dit jamais les choses qu’à moitié.",scenes:["Qui s’occupe le plus des parents ? Personne ne le dit, mais au fond chacun tient les comptes.","Vous faites une plaisanterie dans le groupe, l’autre ne répond pas, et quelques jours plus tard vous découvrez qu’il était vexé."],advice:"Quand quelque chose coince, parlez-en tôt : plus on attend, plus c’est difficile à réparer."},
'天同·天梁':{title:"Une grande famille où l’on est protégé",story:"Vos frères et sœurs ou proches du même âge sont bons et attentionnés, avec une entraide entre aînés et cadets. Votre relation est stable et chaleureuse, et dans les moments difficiles quelqu’un intervient souvent de lui-même. La friction : trop de dépendance, ou c’est toujours la même personne qui porte le plus.",scenes:["Vous êtes débordé, et votre sœur va chercher votre enfant à l’école de son propre chef, et le fait dîner au passage.","Vous êtes peut-être celui qu’on invite souvent à dîner pour l’écouter se confier toute la soirée."],advice:"Quand on prend soin de vous, rendez la pareille ; quand vous prenez soin des autres, gardez du temps pour vous reposer."},
'廉貞':{title:"Des compagnons entiers dans l’amour comme dans la colère",story:"Vos frères et sœurs ou proches du même âge ont du caractère et des principes ; les sentiments sont intenses mais les limites nettes. Des valeurs différentes peuvent créer des frictions, tout en vous laissant une sincère admiration mutuelle. Lian Zhen apporte une note de compétition, et la fratrie se compare facilement en silence. Quand il se passe vraiment quelque chose, ils vous soutiennent.",scenes:["Enfants, votre sœur et vous compariez vos notes ; adultes, vous comparez travail, logement et enfants.","Vous organisez peut-être un événement avec un proche : son exigence rend le résultat superbe, et le processus épuisant."],advice:"Remplacez la comparaison par l’apprentissage mutuel : vous serez tous beaucoup plus détendus."},
'廉貞·天府':{title:"Un domaine familial bien réglé",story:"Vos frères et sœurs ou proches du même âge sont posés et mesurés, et savent gérer et administrer. Vos échanges sont ordonnés ; la relation n’est pas fusionnelle, mais très fiable. Face aux questions d’argent ou de famille, ils agissent avec calme et raison. La friction : chacun a ses propres exigences.",scenes:["Pour organiser la retraite de vos parents, vous vous répartissez les tâches comme en réunion, chacun sait exactement ce qu’il a à faire.","Vous travaillez peut-être avec un proche qui tient les comptes impeccablement, mais vous y trouvez un manque de chaleur."],advice:"Ajoutez de la chaleur à l’ordre : de temps en temps, partagez un repas sans ordre du jour."},
'廉貞·天相':{title:"Le médiateur qui arrondit toujours les angles",story:"Vos frères et sœurs ou proches du même âge sont attachés aux liens et aux règles, et jouent souvent le rôle de médiateur. Votre relation est assez influencée par l’environnement, et les grands événements familiaux vous touchent tous. L’appui : quelqu’un vous aide à gérer les choses compliquées. La friction vient souvent des règles ou de la face.",scenes:["Quand un différend éclate dans la famille, votre cousin est toujours celui qui arbitre, et qui archive même les échanges.","Vous signez peut-être un bail avec un ami qui se soucie plus que vous de chaque clause de résiliation."],advice:"Remerciez celui qui fait toujours la médiation, et ne le laissez pas tout porter seul."},
'廉貞·七殺':{title:"Une petite troupe qui monte à l’assaut",story:"Vos frères et sœurs ou proches du même âge sont décidés et pleins d’allant ; tout le monde a un caractère bien trempé, les échanges sont directs et les étincelles inévitables. Quand vous agissez ensemble, vous obtenez des résultats ; quand vous vous disputez, les mots peuvent être durs. Dans l’adversité, ce sont des compagnons d’armes qui se battent à vos côtés.",scenes:["Vous emmenez vos parents à l’étranger avec votre frère, programme chargé chaque jour, et au retour tout le monde a maigri de fatigue.","Vous décrochez peut-être un contrat avec un associé de votre âge, puis vous vous disputez le mérite au dîner de célébration."],advice:"Clarifiez d’abord l’objectif commun : votre énergie ne se perdra pas en conflits internes."},
'廉貞·破軍':{title:"Une saga familiale au scénario sans cesse réécrit",story:"Vos frères et sœurs ou proches du même âge ont une personnalité forte et le goût de l’aventure ; la relation fluctue nettement, faite de ruptures et de retrouvailles, ou de vies très différentes. Pour s’associer, attention aux imprévus, et gardez de la marge côté trésorerie. L’avantage : ils vous ouvrent souvent à de nouvelles possibilités.",scenes:["Votre sœur décide soudain de s’installer à l’étranger, et la famille tient plusieurs conseils à ce sujet.","Vous menez peut-être un projet avec un ami qui propose, à mi-parcours, de tout reprendre à zéro."],advice:"En collaborant avec eux, restez souple tout en tenant vos propres limites."},
'廉貞·貪狼':{title:"Des compagnons qui adorent la nuit",story:"Vos frères et sœurs ou proches du même âge sont très sociables et aiment l’animation ; leur vie est riche et colorée. Vos échanges se passent souvent en soirée ou dans les loisirs, et quand tout va bien, on se dit tout. Les frictions concernent surtout les dépenses, les cercles d’amis ou les limites ; plus la fête est folle, plus il faut tenir les comptes.",scenes:["Votre frère vous emmène à un concert, vous enchaînez ensuite, et vous rentrez à trois heures du matin.","Lors d’une soirée entre amis, on vous pousse à payer la tournée, et le lendemain la notification bancaire vous fait regretter."],advice:"Avant de sortir ensemble, fixez un budget : on peut s’amuser tout en préservant son portefeuille."},
'天府':{title:"Le voisin fiable à côté du grenier",story:"Vos frères et sœurs ou proches du même âge sont posés, tolérants et savent préserver l’acquis ; vous vous entendez paisiblement. Leur aide est très concrète : s’occuper d’un membre de la famille, avancer de l’argent au bon moment. La relation n’est pas passionnée, mais fiable sur la durée. La friction : ils sont plutôt conservateurs et n’aiment pas le risque.",scenes:["Vous annoncez vouloir démissionner pour créer votre entreprise ; votre sœur vous soutient, mais vous rappelle d’abord de mettre de côté six mois de frais de vie.","Vous êtes sans doute habitué à ce que votre frère organise les repas de fête, il suffit d’être présent."],advice:"Chérissez cette stabilité, et parlez-leur de vos projets pour les rassurer."},
'太陰':{title:"Un doux clair de lune près de la fenêtre",story:"Vos frères et sœurs ou proches du même âge sont tendres et délicats, et l’influence des sœurs ou des amies est plus marquée. Vos échanges sont plutôt calmes, l’attention se cache dans les petits gestes. {{B:太陰:Vous êtes attentionnés l’un envers l’autre et votre lien est stable.|La relation est plutôt distante, ou les émotions créent facilement des malentendus.}}",scenes:["Pour votre anniversaire, votre petite sœur ne fait rien de spectaculaire, mais vous envoie une boîte des biscuits que vous adoriez enfant.","Une remarque anodine de votre cousine vous attriste peut-être pendant plusieurs jours."],advice:"La délicatesse est une qualité ; quand vous êtes triste, dites-le, pour que l’autre puisse se rattraper."},
'貪狼':{title:"Des compagnons joueurs aux multiples talents",story:"Vos frères et sœurs ou proches du même âge sont doués et sociables ; avec eux, c’est amusant et animé, mais il peut y avoir un peu de comparaison : qui est le plus populaire, qui gagne le mieux. L’appui : ils vous font découvrir de nouveaux cercles. La friction : les dépenses et les tentations.",scenes:["Votre frère cadet vous entraîne dans son club de jeux de société, et vous y rencontrez votre partenaire de travail actuel.","Vous partagez peut-être des passions avec un proche, du camping à la photo, avec l’équipement complet pour chacune."],advice:"Profitez de l’animation qu’ils apportent, tout en sachant ce que vous voulez vraiment."},
'巨門':{title:"Une porte qui ferme mal",story:"Vos frères et sœurs ou proches du même âge s’expriment bien et observent finement, mais la communication bloque souvent, et les malentendus viennent surtout du ton ou des propos rapportés. L’avantage : ils analysent bien et osent remettre en question, ce qui vous aide à voir vos angles morts. Il suffit d’accepter de mettre les choses au clair pour réparer la relation.",scenes:["À une réunion de famille, un « tu as pris du poids, non ? » suffit à vous couper l’appétit pour la soirée.","Vous travaillez peut-être avec un associé qui remet en question chaque dépense : c’est agaçant, mais il vous fait vraiment économiser."],advice:"Dites les choses importantes en face, sans laisser les messages et les intermédiaires les interpréter pour vous."},
'天相':{title:"Celui qui vous tend toujours un parapluie",story:"Vos frères et sœurs ou proches du même âge sont bons, polis et serviables, souvent dans le rôle de soutien et de médiateur. Votre relation est paisible et respectueuse. L’appui : quelqu’un s’occupe des détails et des relations pour vous. La friction : tout le monde est trop poli, et les vraies pensées restent cachées.",scenes:["Quand vous déménagez, votre cousine dresse discrètement la liste des cartons et contacte même le déménageur.","Coincé entre deux amis qui se disputent, vous voyez les deux venir se plaindre auprès de vous."],advice:"Ajoutez un peu de franchise à la politesse : la relation n’en sera que plus vraie."},
'天梁':{title:"Le vieil arbre qui fait de l’ombre devant la maison",story:"Vos frères et sœurs ou proches du même âge sont mûrs et protecteurs, souvent dans le rôle de l’aîné ou du gardien ; il y a peut-être un grand écart d’âge, ou l’un de vous a mûri particulièrement tôt. {{B:天梁:Leur protection est forte : quand il se passe quelque chose, quelqu’un vous couvre.|Leur sollicitude s’accompagne de remontrances qui vous étouffent un peu.}}",scenes:["Avant votre changement d’emploi, votre frère compare pour vous les avantages et les perspectives de trois entreprises.","Vous êtes peut-être celui qu’on appelle toujours pour régler les problèmes, et votre téléphone sonne souvent en pleine nuit."],advice:"Remerciez-les quand ils prennent soin de vous, et faites-leur comprendre en douceur que vous avez grandi."},
'七殺':{title:"Deux sentinelles chacune à son poste",story:"Vos frères et sœurs ou proches du même âge sont indépendants et décidés, chacun a son propre champ de bataille. Vous n’êtes pas souvent ensemble, mais vous vous soutenez dans les grands moments. Associés, vous êtes efficaces ; en désaccord, l’affrontement est frontal. Pour la trésorerie, vous comptez plutôt sur vous-même que sur la famille.",scenes:["Faut-il vendre la maison familiale ? Une seule réunion suffit pour trancher, mais l’ambiance est explosive.","En collaborant avec un ami rapide et tranchant, vous devez accélérer pour suivre."],advice:"Respectez l’indépendance de chacun, et fixez des moments réguliers pour vous donner des nouvelles, afin de ne pas vous perdre de vue."},
'破軍':{title:"Un voyage fait de déménagements sans fin",story:"Vos frères et sœurs ou proches du même âge ont une forte personnalité et aiment le changement ; la relation se rapproche et s’éloigne, vous vivez peut-être dans des villes différentes, ou vos trajectoires de vie divergent beaucoup. Pour vous associer, prévoyez de la marge pour les changements, et ne comptez pas trop sur les autres pour la trésorerie. L’avantage : ils vous donnent le courage de casser les vieux cadres.",scenes:["Votre sœur a changé quatre fois de travail en trois ans, en disant à chaque fois « cette fois, c’est la bonne ».","Vous ouvrez peut-être un studio avec un vieil ami ; six mois plus tard, vos idées ont changé et vous vous séparez à l’amiable."],advice:"Voyez le changement comme leur état normal ; à vous de garder votre propre rythme."},
'空':{title:"Un miroir qui reflète le palais opposé",story:"Le palais de la Fratrie n’a pas d’étoile majeure : pour lire vos liens avec la fratrie et les proches du même âge, on emprunte les étoiles du palais opposé, celui des Amis, et l’environnement et les étapes de la vie comptent beaucoup. Vos échanges avec vos frères et sœurs sont très variables, proches à une période, distants à une autre. Où vous êtes et qui vous entoure détermine souvent la forme de ce lien.",scenes:["Enfant, vous parliez à peine avec votre frère ; adultes, installés dans la même ville, vous êtes devenus de bons amis.","Après un changement de travail ou un déménagement, les proches de votre âge que vous fréquentez sont entièrement renouvelés."],advice:"Choisissez activement les personnes dont vous voulez vous rapprocher : la forme de vos liens peut être façonnée par vous."}
},
'僕役':{
'紫微':{title:"Des amis qui veulent tous le premier rôle",story:"Zi Wei dans le palais des Amis : vos amis ont souvent du statut et des compétences, et votre réseau est de bon niveau. Mais des amis et collaborateurs compétents n’obéissent pas forcément à vos ordres ; parfois c’est vous qui vous adaptez à eux. L’appui : votre cercle compte des personnes influentes. La friction : qui mène et qui cède.",scenes:["Le nouveau que vous encadrez est très compétent, et propose souvent en réunion une direction totalement différente de la vôtre.","À une réunion d’anciens élèves, vous découvrez que tout le monde est devenu manager ou patron, et la conversation ressemble à un conseil d’administration."],advice:"Partagez la scène et laissez de l’espace aux talents : ils deviendront vos alliés."},
'紫微·天府':{title:"Un porte-cartes rempli d’invités de marque",story:"Votre cercle d’amis est de haut niveau, posé et solide, avec des ressources abondantes. Vos échanges reposent sur l’envergure et la réciprocité, sans politesses inutiles. L’appui : votre réseau apporte des occasions concrètes. La friction : chacun a ses idées et ne suit pas forcément votre rythme.",scenes:["Un aîné rencontré lors d’un dîner vous présente six mois plus tard un gros client.","Vous dirigez peut-être une équipe solide où chacun a sa méthode : coordonner compte plus que donner des ordres."],advice:"Entretenir un réseau, c’est de la réciprocité sur la durée : ne prenez pas contact seulement quand vous avez besoin d’aide."},
'紫微·天相':{title:"Un dîner où l’étiquette compte",story:"Vos amis et collègues soignent leur image et respectent les usages ; les échanges sont convenables. Dans votre cercle, on attend souvent de vous que vous veilliez à l’ensemble et teniez la situation. L’appui : quelqu’un accepte de faire les présentations et de se porter garant pour vous. La friction : tout est harmonieux en surface, chacun calcule en privé.",scenes:["À la fête de fin d’année, on vous place à la table de la direction, et vous passez la soirée à faire la conversation et à trinquer.","Vous présentez deux amis pour qu’ils travaillent ensemble, ils ne s’entendent pas, et vous voilà à apaiser les deux côtés."],advice:"Avant de mettre des gens en relation, renseignez-vous sur les deux : vous n’êtes pas responsable de chaque relation."},
'紫微·破軍':{title:"Une expédition dont l’équipage change souvent",story:"Vos amis ont souvent du caractère et le goût du risque ; votre cercle change beaucoup, un groupe à une étape, un autre à la suivante. Vos collaborateurs sont compétents mais difficiles à encadrer, et vont et viennent peut-être. L’appui : vous rencontrez des gens de nouveaux domaines, et votre horizon ne cesse de s’élargir.",scenes:["Vous rejoignez une communauté d’entrepreneurs, et un an plus tard la moitié des membres clés a changé.","Vous avez peut-être encadré un collaborateur très doué qui, après de beaux résultats, s’est mis à son compte."],advice:"Acceptez les allées et venues, et saisissez la valeur de chaque collaboration au moment présent."},
'紫微·七殺':{title:"Des chefs ayant chacun leur territoire",story:"Vos amis et collègues ont un caractère fort, de bonnes compétences et agissent avec décision. Vous vous respectez, mais les rapports de pouvoir ne manquent pas. L’appui : dans les batailles difficiles, quelqu’un tient bon. La friction : personne ne veut être dirigé, et les réunions tournent au bras de fer.",scenes:["Dans le groupe projet, tout le monde est fort, et dès la première réunion on se dispute une heure sur la répartition des tâches.","Vous vous faites peut-être un ami au ton abrupt, qui est pourtant le premier à appeler quand vous êtes au plus bas."],advice:"Avec les fortes personnalités, expliquez l’objectif plutôt que de donner des ordres : vous obtiendrez une vraie coopération."},
'紫微·貪狼':{title:"Une fête constellée d’étoiles",story:"Vos amis sont doués, savent s’amuser, très sociables, avec un large réseau. Votre vie est souvent animée grâce à eux, et les sorties se multiplient. La friction concerne l’argent, le temps et les limites : il faut distinguer les vrais amis de ceux avec qui on ne fait que boire un verre.",scenes:["Trois soirs par semaine, on vous invite à dîner, et le relevé de carte de fin de mois vous fait sursauter.","Lors d’une soirée, vous rencontrez peut-être la personne qui vous aidera à changer de métier, et aussi quelqu’un qui ne vient vous voir que pour emprunter."],advice:"Réservez votre temps en priorité aux amis qui comptent vraiment : au-delà de l’animation, il faut aussi des liens profonds."},
'天機':{title:"Une bande de cerveaux rapides pleins d’idées",story:"Vos amis sont intelligents et bien informés, et les conversations sont riches. Votre cercle évolue souvent avec l’environnement : un nouveau travail, un nouveau groupe d’amis. {{B:天機:Votre réseau est souple, il y a toujours quelqu’un pour vous conseiller ou trouver une information.|Beaucoup d’échanges mais peu de vraies confidences, et les projets s’arrêtent facilement en cours de route.}}",scenes:["Vous demandez dans un groupe quel dentiste choisir, et en dix minutes vous recevez dix recommandations et trois comparatifs.","Vous convenez peut-être avec un collègue de lancer une activité annexe ; les discussions sont passionnées, puis chacun est pris par ses affaires et l’idée tombe à l’eau."],advice:"Parmi tous ces esprits brillants, repérez une ou deux personnes prêtes à aller au bout des choses avec vous."},
'天機·太陰':{title:"Une longue lettre à un vieil ami",story:"Vos amis sont délicats, doux et pleins d’idées ; vous préférez peu d’amis mais de qualité, et les amies ou collègues femmes prennent souvent particulièrement soin de vous. Les amitiés évoluent avec les déménagements et les changements de poste, mais les vrais amis restent. La friction : vous êtes tous sensibles, et les malentendus se dissipent mal.",scenes:["Des années après votre départ, une ancienne collègue vous envoie encore de temps en temps une photo du café où vous alliez ensemble.","Parce que des amis ne vous ont pas invité à une sortie, vous vous demandez peut-être pendant plusieurs jours si l’on vous tient à l’écart."],advice:"Chérissez ces amitiés au long cours, et quand un doute vous habite, prenez contact vous-même."},
'天機·巨門':{title:"Un club de lecture animé",story:"Vos amis sont intelligents et éloquents, aiment débattre et analyser ; vos échanges sont profonds et stimulent souvent vos idées mutuelles. Les frictions viennent des accrochages verbaux et des malentendus : attention aux commentaires dans le dos et aux propos rapportés.",scenes:["Vous discutez d’actualité avec un ami jusqu’à en rougir, et le lendemain vous prenez le petit-déjeuner ensemble.","Vous encadrez peut-être une équipe qui pose beaucoup de questions : chaque proposition doit passer plusieurs rounds de contestation."],advice:"Appréciez leur esprit critique, et convenez ensemble d’une règle de discussion : on parle des faits, pas des personnes."},
'天機·天梁':{title:"De vieux amis qui adorent jouer les conseillers",story:"Vos amis ont beaucoup d’expérience et aiment conseiller ; vous êtes entouré de nombreuses personnes plus âgées ou plus expérimentées. Vos échanges ressemblent à des consultations mutuelles, chacun apprend de l’autre. L’appui : quelqu’un vous guide quand il y a un souci. La friction : trop de conseils, un ton un peu moralisateur.",scenes:["Vous évoquez une idée d’entreprise, et vos amis évaluent les risques à tour de rôle.","Vous êtes peut-être la personne que les nouveaux consultent le plus dans l’entreprise, et l’on vous demande dix fois par jour « comment on fait ça ? »."],advice:"Après avoir écouté les conseils, gardez votre propre jugement : ne laissez pas les avis noyer votre décision."},
'太陽':{title:"La lampe qui éclaire toute l’équipe",story:"Vos amis sont chaleureux et généreux, et dans vos relations vous êtes souvent celui qui donne ; l’aide des amis ou collègues masculins est plus marquée. {{B:太陽:Vous êtes apprécié, et ce que vous donnez vous est rendu.|Vous aidez avec ardeur sans qu’on s’en souvienne vraiment, et vous vous fatiguez facilement.}}",scenes:["Un collègue fait des heures supplémentaires, vous allez lui chercher à manger et restez jusqu’à ce qu’il ait fini.","Vous prêtez peut-être de l’argent à un ami en difficulté, et ensuite il n’en reparle presque jamais."],advice:"Donnez avec cœur, mais choisissez vos destinataires : que votre bienveillance aille à ceux qui savent l’apprécier."},
'太陽·太陰':{title:"Des compagnons qui se relaient jour et nuit",story:"Vos amis sont hommes et femmes, chaleureux ou doux : votre cercle est très varié. Votre vie sociale suit votre humeur et les étapes de la vie, très active parfois, et parfois vous n’aspirez qu’au calme. Différents types d’amis vous soutiennent à différents moments.",scenes:["Le jour, vous débattez avec vos collègues en réunion ; le soir, vous parlez tranquillement de choses intimes avec un vieil ami dans un petit bar.","Une période, vous adorez les sorties ; la suivante, vous voulez rester seul."],advice:"Acceptez votre rythme social : pas besoin de vous forcer à être aussi entouré à chaque étape."},
'太陽·巨門':{title:"Une station de radio animée",story:"Vos amis sont chaleureux et bavards, et l’information circule vite dans votre cercle. Vous êtes faits pour promouvoir, faire du marketing ou enseigner ensemble, avec une voix qui porte et un fort pouvoir de diffusion. La friction : les commérages, les propos se déforment en circulant, et une plaisanterie peut être prise au sérieux.",scenes:["Vous lâchez une plainte en passant dans un groupe, et le lendemain tout le service est au courant.","Vous faites peut-être des directs ou des conférences avec un ami, et votre éloquence attire un public fidèle."],advice:"Avant de parler, pensez aux oreilles que vos paroles atteindront, et mettez votre éloquence au bon endroit."},
'太陽·天梁':{title:"Un grand arbre où l’on vient se mettre à l’ombre",story:"Vos amis sont fidèles et ont le sens de la justice ; dans vos relations, on vous voit souvent comme quelqu’un sur qui compter, et vous ne manquez pas d’aînés et de mentors bienveillants. L’appui : l’entraide. La friction : vous gérez trop, prenez trop soin des autres, et ne savez plus où donner de la tête.",scenes:["Des amis vous appellent souvent pour arbitrer leurs différends, et vous finissez par tout savoir de leurs affaires de famille.","Vous êtes peut-être celui qui forme discrètement les nouveaux dans votre service, et vous répondez encore à leurs questions après le travail."],advice:"Prendre soin des autres demande aussi des limites : apprenez à dire « essaie d’abord tout seul »."},
'武曲':{title:"Des gens d’action qui misent sur l’efficacité",story:"Vos amis sont pragmatiques et directs, et vos échanges tournent souvent autour du travail ou de l’argent. Vos relations reposent sur l’équilibre des intérêts, et vous passez peu de temps à entretenir l’affectif. {{B:武曲:Votre réseau vous apporte des occasions concrètes.|Les échanges créent facilement des frictions autour de l’argent.}}",scenes:["Vous prenez une mission avec un ami, et sa première question est de savoir comment partager la rémunération.","Vos collaborateurs sont peut-être efficaces mais bavardent rarement, et l’ambiance de l’équipe est plutôt froide."],advice:"Au-delà des intérêts bien clarifiés, invitez parfois tout le monde à dîner : les liens aussi demandent un investissement."},
'武曲·天府':{title:"De vieux amis bien établis",story:"Vos amis ont des moyens stables et sont solides, et votre réseau apporte ressources et occasions. Vos échanges reposent sur la confiance, et les relations durent généralement longtemps. La friction : tout le monde est plutôt conservateur, et faire avancer une idée nouvelle demande beaucoup d’efforts.",scenes:["Vous cherchez une salle pour un événement, et un vieil ami vous prête directement la salle de réunion de son entreprise.","Vous dirigez peut-être une équipe très stable, mais introduire un nouveau fonctionnement rencontre une forte résistance."],advice:"Chérissez cette fiabilité, et pour une nouveauté, prenez le temps de convaincre chacun."},
'武曲·天相':{title:"Des coéquipiers fiables qui respectent les règles",story:"Vos amis et collègues sont sérieux et tiennent parole, et acceptent de vous aider. Vos échanges sont équitables, on se doit rarement quelque chose. La friction : trop de règles, peu de souplesse quand il faut s’adapter, et un changement de plan de dernière minute inquiète tout le monde.",scenes:["Dans l’équipe, chacun rend sa part à l’heure, personne n’a besoin d’être relancé.","Vous demandez peut-être à un ami de relire un contrat ; il annote chaque clause et entoure même les fautes de frappe."],advice:"Transformez la confiance en complicité, et accordez-vous de temps en temps un peu de souplesse."},
'武曲·七殺':{title:"Une troupe à la discipline de fer",story:"Vos amis ont un caractère ferme et agissent avec décision ; les échanges sont directs, sans bavardage. Ensemble, vous pouvez accomplir des missions difficiles, mais les conflits sont frontaux. Vos collaborateurs sont compétents, mais ont besoin de consignes et d’objectifs clairs : plus votre direction est nette, plus ils foncent.",scenes:["En période de rush, tout le monde veille ensemble, puis se dispute à taper du poing sur la table pour une décision.","Vous devenez peut-être ami avec quelqu’un rencontré à la salle de sport, une amitié bâtie sur la sueur partagée."],advice:"Clarifiez règles et objectifs : une équipe au caractère dur est alors redoutable."},
'武曲·破軍':{title:"Des aventuriers qui se dispersent du jour au lendemain",story:"Vos amis osent foncer et aiment le risque, et votre cercle change beaucoup. Les échanges impliquent souvent de l’argent : prêts et associations demandent une prudence particulière. L’avantage : ils vous font découvrir de nouveaux domaines et des occasions que vous n’auriez pas approchées.",scenes:["Un ami vous propose d’investir ensemble dans un restaurant, plein d’enthousiasme, et six mois plus tard chacun se retire.","Vous avez peut-être eu un collaborateur très doué pour faire du chiffre, mais aux méthodes souvent à la limite des règles."],advice:"Pour toute affaire d’argent, gardez des documents, même avec les meilleurs amis."},
'武曲·貪狼':{title:"Un repas où l’on parle affaires en mangeant",story:"Vos amis savent gagner de l’argent et profiter de la vie, et vie sociale et affaires se mêlent souvent. Votre réseau apporte des occasions, mais aussi beaucoup de sorties. La friction concerne le partage des gains et les dépenses : qui doit payer combien est souvent un sujet difficile à aborder. Avec eux, le pire n’est pas la dispute, mais les comptes tenus en silence.",scenes:["Une conversation pendant une partie de golf vous permet de conclure un contrat.","Vous partez peut-être en voyage avec des amis, et au retour il y a toujours quelqu’un dont les comptes ne tombent pas juste."],advice:"Tenez des comptes séparés pour la vie sociale et les affaires : on s’amuse et on sait où on en est."},
'天同':{title:"Les vieux amis qui partagent votre en-cas de minuit",story:"Vos amis sont doux et faciles à vivre ; vous êtes apprécié et les échanges sont détendus. Il y a peu de conflits d’intérêts entre vous, surtout de la présence et du partage. {{B:天同:Vous avez beaucoup d’amis et des liens chaleureux.|Les amitiés sont bonnes, mais l’aide concrète est plus rare quand vous en avez vraiment besoin.}} Tout le monde est accommodant, et les choses traînent facilement.",scenes:["Un vendredi soir, un simple coup de fil suffit pour trouver quelqu’un avec qui aller manger un morceau.","Vous décidez peut-être avec des amis de perdre du poids ensemble, et trois mois plus tard tout le monde a pris deux kilos."],advice:"Une amitié légère est précieuse ; quand vous avez besoin de vous motiver mutuellement, dites-le."},
'天同·太陰':{title:"Un petit café chaleureux",story:"Vos amis sont tendres et délicats, et les amies ou collègues femmes sont particulièrement attentionnées. Vos échanges tournent autour du soutien affectif et de l’entraide. La friction : personne n’aime le conflit, on garde les choses pour soi, et avec le temps cela crée de la distance.",scenes:["Vous êtes en arrêt maladie, et une collègue range discrètement votre travail en vous laissant un petit mot sur le bureau.","Vous êtes très proche d’un ami, mais vous n’osez jamais lui demander de vous rendre le livre que vous lui avez prêté."],advice:"Au-delà de la douceur, soyez direct : dites ce dont vous avez besoin."},
'天同·巨門':{title:"Une salle de pause à l’ambiance subtile",story:"Vos amis sont aimables en surface, mais en privé les petits malentendus et les commérages surviennent facilement ; dans vos relations, méfiez-vous des propos rapportés et des critiques dans le dos. L’avantage : vous trouvez toujours quelqu’un prêt à écouter, pour vider votre sac ensemble. Mais ce que vous entendez, mieux vaut le prendre avec des pincettes.",scenes:["Vous vous plaignez de votre responsable en passant à la machine à café, et quelques jours plus tard la version qui circule est complètement déformée.","Vous avez peut-être un groupe de collègues avec qui vider votre sac, et les dîners après le travail sont plus animés que le bureau."],advice:"Se plaindre, d’accord, mais réservez les choses importantes aux personnes de confiance."},
'天同·天梁':{title:"De vieux voisins qui veillent les uns sur les autres",story:"Vos amis sont bons et serviables ; l’entraide est très présente dans vos relations, et quand vous êtes en difficulté, quelqu’un vous tend toujours la main. La friction : trop de dépendance mutuelle, ou c’est toujours vous qui prenez soin des autres, au point d’oublier que vous aussi avez besoin qu’on prenne soin de vous.",scenes:["Vous partez dix jours à l’étranger, et vos amis arrosent les plantes, relèvent le courrier et nourrissent le chat d’eux-mêmes.","Vous êtes peut-être la personne la plus serviable du groupe du quartier, c’est même vous qui relayez les avis de coupure d’eau."],advice:"Faites de l’entraide un échange : ce n’est pas toujours à vous de donner en premier."},
'廉貞':{title:"Un cercle d’amis entier dans l’amour comme dans la colère",story:"Vos amis ont une forte personnalité, les liens sont intenses, mais on peut aussi se brouiller pour des valeurs différentes. Au travail, les relations ont un parfum de compétition, et les collègues se comparent en silence. L’appui : aux moments clés, quelqu’un vous soutient. La friction : les relations basculent facilement dans les extrêmes.",scenes:["Vous restez six mois en froid avec un ami pour une broutille, puis un incident vous réconcilie.","Vous sentez peut-être la rivalité discrète entre collègues, et l’ambiance se tend particulièrement avant l’annonce des promotions."],advice:"Choisissez vos amis selon leurs valeurs : inutile de vouloir plaire à tout le monde."},
'廉貞·天府':{title:"Une chambre de commerce aux règles claires",story:"Vos amis sont compétents et savent gérer, et votre réseau est plutôt professionnel. Vos échanges sont ordonnés et concrets ; la relation est stable sans être fusionnelle. La friction : chacun a ses positions, et collaborer demande du temps pour s’ajuster ; négocier les conditions prend souvent plus de temps que le travail lui-même.",scenes:["Vous participez à une rencontre professionnelle, et chaque personne rencontrée arrive avec un objectif de partenariat précis.","L’équipe que vous dirigez est peut-être très disciplinée, mais stimuler la créativité demande plus d’efforts."],advice:"Laissez un peu de chaleur humaine dans les règles : la collaboration sera bien plus fluide."},
'廉貞·天相':{title:"Un réseau qui demande un entretien attentif",story:"Vos amis sont attachés aux liens et aux règles, et vos relations sont très influencées par l’environnement et les structures ; dans un groupe, c’est souvent vous qui coordonnez. L’appui : quelqu’un accepte d’intervenir pour vous. La friction : des conflits nés de règles floues ou de malentendus.",scenes:["Pour un événement d’association, on vous désigne comme interlocuteur, et tout le monde vous envoie ses avis à synthétiser.","Vous acceptez peut-être de vous porter caution ou garant pour un ami, et découvrez ensuite que la responsabilité est plus lourde que prévu."],advice:"Coordonner, oui, mais pour toute signature ou garantie, réfléchissez-y à deux fois."},
'廉貞·七殺':{title:"Des compagnons d’armes côte à côte",story:"Vos amis ont du cran et osent se battre, et vos amitiés naissent souvent dans l’effort commun. En collaboration, l’énergie déborde ; en conflit, ça explose. Vos collaborateurs sont compétents, mais il faut du temps pour accorder vos rythmes ; passé les trois premiers mois, la complicité arrive.",scenes:["Vous survivez avec un collègue à un client très difficile, et vous voilà devenus inséparables.","Vous avez peut-être un collaborateur au fort caractère, très efficace, mais qui ne suit souvent pas la procédure."],advice:"L’objectif commun est votre meilleur ciment : alignez d’abord la direction, puis partez."},
'廉貞·破軍':{title:"Un groupe de musique sans cesse recomposé",story:"Vos amis ont une forte personnalité et aiment l’aventure ; votre cercle change beaucoup, et les relations passent facilement du chaud au froid. Les collaborations sont pleines d’imprévus, et confiance et engagements demandent du temps pour être éprouvés. L’avantage : vous rencontrez toutes sortes de gens, et la vie est rarement ennuyeuse.",scenes:["L’association dont vous faites partie change de bureau chaque année, et les règles changent avec.","Vous menez peut-être un projet avec un ami qui change d’avis en cours de route, et vous devez chercher quelqu’un d’autre."],advice:"Pour les collaborations importantes, prévoyez un plan B, sans tout miser sur une seule personne."},
'廉貞·貪狼':{title:"Un cercle mondain tout illuminé",story:"Vos amis sont très sociables et savent s’amuser, et votre vie relationnelle compte beaucoup de sorties et de soirées. Votre réseau apporte des occasions, mais aussi des tentations. Les frictions concernent surtout les dépenses, les limites et des relations enchevêtrées. Tout en vous amusant, sachez distinguer qui tient vraiment à vous.",scenes:["Un ami vous fait entrer dans un cercle, et depuis vous avez chaque semaine une invitation à une fête.","Avec trop de sorties, vous n’arrivez peut-être même plus à garder un week-end entier pour vous."],advice:"Soyez sélectif, et gardez votre temps pour les personnes qui vous font grandir."},
'天府':{title:"Un grenier solide de relations",story:"Vos amis sont posés et tolérants ; votre cercle n’est pas forcément grand, mais il est fiable. Amis et collaborateurs font généralement leur part et vous aident à préserver vos acquis. La friction : tout le monde est plutôt conservateur, et il faut du temps pour se lancer ensemble dans la nouveauté.",scenes:["Quand vous êtes en difficulté, un ami de dix ans vous met sans hésiter en relation avec les bonnes ressources.","L’équipe que vous dirigez connaît peut-être très peu de départs, la complicité est excellente, mais les réactions au changement sont lentes."],advice:"Chérissez vos vieux amis et faites aussi de nouvelles rencontres, pour que le grenier reste frais."},
'太陰':{title:"Une douce réunion au clair de lune",story:"Vos amis sont doux et délicats, et l’aide des amies ou collègues femmes est plus marquée. Vous préférez peu d’amis mais de qualité, et tenez aux échanges affectifs. {{B:太陰:Vos amis sont attentionnés et les échanges chaleureux.|Vos relations sont plutôt distantes, et la sensibilité crée facilement de l’éloignement.}}",scenes:["Vous n’avez pas beaucoup de bons amis, mais chacun sait dans quelle pâtisserie acheter votre gâteau préféré.","Vous êtes peut-être plutôt discret en groupe, et c’est une fois rentré que vous écrivez en privé à un ami pour partager vos impressions."],advice:"Prenez vous-même des nouvelles de ceux qui comptent : une amitié silencieuse a aussi besoin d’être arrosée."},
'貪狼':{title:"Une fête où il ne manque jamais personne",story:"Vous avez beaucoup d’amis et un large réseau, et il y a toujours de l’animation autour de vous. Votre réseau apporte des occasions, mais aussi des tentations et des sorties. La friction : distinguer qui est sincère de qui ne fait que s’amuser avec vous ; la profondeur d’un lien se vérifie avec le temps.",scenes:["Votre répertoire compte plus de mille contacts, mais seuls deux ou trois peuvent être appelés en pleine nuit.","Lors d’une soirée, un ami vous fait entrer dans un nouveau cercle, et votre vie prend peut-être un tournant."],advice:"Tout en élargissant votre réseau, sachez qui sont vos vrais amis."},
'巨門':{title:"Une salle de réunion où l’écho résonne",story:"Vos amis sont éloquents et observateurs, mais vos relations sont sujettes aux commérages, et les malentendus avec amis et collègues viennent surtout de la communication. L’avantage : ils vous aident à voir les problèmes et proposent des idées auxquelles vous n’aviez pas pensé ; si vous savez écouter, c’est un vrai appui.",scenes:["Vous présentez une proposition en réunion, et un collègue vous lance aussitôt dix questions.","Un ami se méprend peut-être sur le sens d’une de vos phrases, et vous restez en froid plusieurs semaines avant de vous expliquer."],advice:"Dites les choses importantes en face, confirmez-les par écrit, et comptez moins sur les intermédiaires."},
'天相':{title:"Des aides fiables",story:"Vos amis et collègues sont bons, polis et serviables ; vous obtenez facilement du soutien, et jouez souvent le rôle de médiateur. La friction : tout le monde tient tant à l’harmonie que les problèmes ne sont pas nommés, et plus on attend, plus c’est difficile à régler.",scenes:["Quand vous êtes débordé, un collègue vous demande spontanément : « Tu veux que je m’occupe de ce tableau ? »","Vous jouez peut-être les conciliateurs entre amis, en gardant vos propres opinions cachées."],advice:"Fondez l’harmonie sur la franchise : dites les choses, la relation n’en sera que plus stable."},
'天梁':{title:"Des amis qui ressemblent à des aînés",story:"Vos amis sont mûrs et protecteurs ; dans vos relations, des personnes plus âgées et expérimentées vous tendent souvent la main, et vous êtes peut-être aussi celui qui prend soin des autres. {{B:天梁:Vous avez beaucoup de protecteurs et un soutien important.|Leur sollicitude s’accompagne d’un certain poids ou de leçons de morale.}}",scenes:["Quand votre carrière piétine, un aîné vous invite de lui-même à prendre un café et vous aide à y voir clair.","Vous êtes peut-être le « chef de famille » de votre cercle d’amis, celui qu’on vient consulter en premier."],advice:"Acceptez qu’on prenne soin de vous et pensez à rendre la pareille : entre protecteurs, on se fait grandir mutuellement."},
'七殺':{title:"Des braves qui partent chacun en campagne",story:"Vos amis sont indépendants et décidés, chacun avec ses objectifs. Votre amitié ne tient pas à des rencontres quotidiennes, mais au soutien dans les moments clés. Vos collaborateurs sont compétents mais pas faciles à diriger, habitués à juger par eux-mêmes avant d’agir. Donnez-leur de l’espace, ils vous rendront des résultats.",scenes:["Vous ne voyez votre meilleur ami que deux fois par an, mais quand il vous arrive quelque chose, il est le premier à appeler.","Vos collaborateurs ont peut-être beaucoup de cran, mais passent souvent à l’action avant même de vous en avoir parlé."],advice:"Remplacez le contrôle par la confiance : les forts ont besoin d’une scène, pas d’une bride."},
'破軍':{title:"Une porte tournante qui s’ouvre et se ferme sans cesse",story:"Vos amis vont et viennent, votre cercle change beaucoup, et vous vous faites peut-être des amis très différents selon les étapes. Le roulement de vos collaborateurs est plutôt élevé, et les partenariats évoluent vite. L’avantage : vous rencontrez sans cesse de nouvelles personnes et de nouveaux points de vue, et stagnez rarement.",scenes:["Après vos études, vous vous éloignez de vos amis de fac, mais dans votre nouveau travail vous rencontrez des gens qui partagent vos idées.","Dans l’équipe que vous dirigez, la moitié des membres sont peut-être nouveaux chaque année, et former devient votre quotidien."],advice:"Inutile de vouloir retenir tout le monde : saisissez la valeur de chaque rencontre."},
'空':{title:"Un miroir qui emprunte la lumière du palais opposé",story:"Le palais des Amis n’a pas d’étoile majeure : pour lire vos relations, on emprunte les étoiles du palais opposé, celui de la Fratrie, et l’environnement compte beaucoup. Votre cercle d’amis est très souple : nouvel environnement, nouveau groupe, et qui vous entoure dépend surtout de l’endroit où vous êtes. L’avantage : une grande capacité d’adaptation, vous vous intégrez dans des groupes variés.",scenes:["Vous avez un groupe d’amis à l’école, un au travail et un dans votre club de loisirs, qui ne se connaissent pas du tout.","Après un déménagement dans une nouvelle ville, vous vous construisez peut-être un nouveau réseau en trois mois."],advice:"Choisissez activement les personnes dont vous voulez vous rapprocher : que l’environnement ne décide pas seul de vous, et que vous décidiez aussi."}
}
});
